create or replace view public.salesperson_party_performance_report with (security_invoker=true) as
with payments as (select sales_order_id,company_id,business_unit_id,sum(amount) received_amount from public.invoice_payment_allocations group by sales_order_id,company_id,business_unit_id),
returns as (select sales_order_id,company_id,business_unit_id,sum(total) return_amount from public.return_notes where note_type='sales_credit' and status='posted' group by sales_order_id,company_id,business_unit_id)
select so.user_id,so.company_id,so.business_unit_id,so.salesperson_id,so.customer_id,c.name as customer_name,count(*)::int as total_orders,sum(coalesce(so.total,0)) as gross_sales,sum(coalesce(r.return_amount,0)) as returns,sum(coalesce(so.total,0)-coalesce(r.return_amount,0)) as net_sales,sum(coalesce(p.received_amount,so.paid_amount,0)) as total_received,greatest(sum(coalesce(so.total,0)-coalesce(r.return_amount,0))-sum(coalesce(p.received_amount,so.paid_amount,0)),0) as debit_balance,greatest(sum(coalesce(p.received_amount,so.paid_amount,0))-sum(coalesce(so.total,0)-coalesce(r.return_amount,0)),0) as credit_balance
from public.sales_orders so left join public.customers c on c.id=so.customer_id and c.company_id=so.company_id left join payments p on p.sales_order_id=so.id and p.company_id=so.company_id and p.business_unit_id is not distinct from so.business_unit_id left join returns r on r.sales_order_id=so.id and r.company_id=so.company_id and r.business_unit_id is not distinct from so.business_unit_id
where so.status='posted' and so.salesperson_id is not null and so.customer_id is not null group by so.user_id,so.company_id,so.business_unit_id,so.salesperson_id,so.customer_id,c.name;
grant select on public.salesperson_party_performance_report to authenticated;
